WITH valid AS (SELECT id, session_id, page, event_time, ROUND(duration_sec * 1.15, 2) AS duration_sec_adjusted FROM web_events WHERE event_time >= DATE '2023-07-05' AND page IS NOT NULL), enriched AS (SELECT *, SUM(duration_sec_adjusted) OVER (PARTITION BY session_id ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_duration_sec_adjusted, FIRST_VALUE(duration_sec_adjusted, TRUE) OVER (PARTITION BY page, session_id ORDER BY duration_sec_adjusted, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_duration_sec_adjusted, DENSE_RANK() OVER (PARTITION BY page ORDER BY duration_sec_adjusted DESC NULLS FIRST) AS duration_sec_adjusted_dense_rank FROM valid WHERE session_id IN (10, 15)), with_gaps AS (SELECT *, CASE WHEN event_time - LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time, id) > INTERVAL 60 DAYS THEN 1 ELSE 0 END AS is_new_session FROM enriched), sessionized AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY session_id ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM with_gaps), scored AS (SELECT *, SUM(duration_sec_adjusted) OVER (PARTITION BY session_id, page ORDER BY is_new_session, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sum_duration_sec_adjusted, COUNT(duration_sec_adjusted) OVER (PARTITION BY session_id, page ORDER BY is_new_session, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_count_duration_sec_adjusted, MIN(duration_sec_adjusted) OVER (PARTITION BY session_id, page ORDER BY is_new_session, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_min_duration_sec_adjusted, NTILE(10) OVER (PARTITION BY session_id ORDER BY cumulative_duration_sec_adjusted DESC, id) AS cumulative_duration_sec_adjusted_bucket FROM sessionized), wide AS (SELECT * FROM (SELECT session_id, page, duration_sec_adjusted FROM scored) src PIVOT (MAX(duration_sec_adjusted) AS total, COUNT(1) AS cnt FOR page IN ('/search' AS search, '/cart' AS cart))) SELECT s.session_id, s.search_total, s.search_cnt, s.cart_total, (SELECT MAX(x.duration_sec) FROM web_events x WHERE x.session_id = s.session_id) AS max_web_event_duration_sec FROM wide s
